function drawWrappedText(
  ctx: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  maxWidth: number,
  lineHeight: number,
  maxLines = 3
): number {
  return drawArcadeTextBlock(ctx, {
    x,
    y,
    width: maxWidth,
    text,
    lineHeight,
    maxLines,
    font: ctx.font,
    align: ctx.textAlign,
    baseline: ctx.textBaseline,
    color: typeof ctx.fillStyle === 'string' ? ctx.fillStyle : ETHIC_UI.text,
  }).height;
}

function command(id: string, label: string, keyboard: string, priority = 0): ArcadeCommandAction {
  return { id, label, inputs: { keyboard }, priority };
}

const itemAtlasImages = new Map<string, HTMLImageElement>();

function renderItemIcon(
  ctx: CanvasRenderingContext2D,
  itemId: ItemId,
  x: number,
  y: number,
  size: number
): boolean {
  const icon = getItemIcon(itemId);
  if (!icon) return false;
  let atlas = itemAtlasImages.get(icon.atlasPath);
  if (!atlas) {
    atlas = new Image();
    atlas.src = icon.atlasPath;
    itemAtlasImages.set(icon.atlasPath, atlas);
  }
  if (!atlas.complete || atlas.naturalWidth === 0) return false;
  ctx.drawImage(atlas, icon.column * 128, icon.row * 128, 128, 128, x, y, size, size);
  return true;
}

function renderCharacterSpritePreview(
  ctx: CanvasRenderingContext2D,
  characterId: CharacterId,
  centerX: number,
  baselineY: number,
  maxWidth: number,
  maxHeight: number,
  opacity = 1,
  flipX = false
): boolean {
  const animMap = getCharacterAnimationMap(characterId);
  if (!animMap?.atlas) return false;
  const idleClip = getStateClip(animMap, 'idle');
  const clipFrame = idleClip?.frames[0];
  if (!clipFrame) return false;
  const atlasFrame = getAtlasFrame(animMap, clipFrame);
  if (!atlasFrame) return false;
  const scale = Math.min(maxWidth / atlasFrame.frameWidth, maxHeight / atlasFrame.frameHeight);
  return renderSpriteFrame(ctx, animMap.atlas, atlasFrame, centerX, baselineY, {
    flipX,
    opacity,
    scale,
  });
}

